package com.ielts.speaking.data.repository

import com.ielts.speaking.data.model.*

object WritingDataProvider {

    data class WritingSetInfo(
        val title: String,
        val theme: String,
        // Q1: Task 1 Data Report
        val q1Title: String,
        val q1Prompt: String,
        val q1Report: String,
        val q1Vocab: List<Band9Vocabulary>,
        // Q2: Task 2 Discursive Essay
        val q2Title: String,
        val q2Prompt: String,
        val q2Essay: String,
        val q2Vocab: List<Band9Vocabulary>,
        // Q3: Task 1 Letter / Process
        val q3Title: String,
        val q3Prompt: String,
        val q3Letter: String,
        val q3Vocab: List<Band9Vocabulary>,
        // Q4: Task 2 Discussion / Problem-Solution
        val q4Title: String,
        val q4Prompt: String,
        val q4Essay: String,
        val q4Vocab: List<Band9Vocabulary>
    )

    fun getWritingPaper(year: Int): WritingYearPaper {
        val cambridgeBookNum = getCambridgeBookForYear(year)
        val sets = listOf(
            buildWritingTestSet(year, 1, cambridgeBookNum),
            buildWritingTestSet(year, 2, cambridgeBookNum),
            buildWritingTestSet(year, 3, cambridgeBookNum),
            buildWritingTestSet(year, 4, cambridgeBookNum)
        )

        return WritingYearPaper(
            year = year,
            title = "IELTS Writing Question Paper ($year • Cambridge IELTS $cambridgeBookNum)",
            description = "Cambridge Official Writing Test Sets 1–4 with Band 9.0 Master Essays, Data Reports & Band Criteria",
            sets = sets
        )
    }

    private fun getCambridgeBookForYear(year: Int): Int {
        return when {
            year >= 2025 -> 20
            year >= 2024 -> 19
            year >= 2023 -> 18
            year >= 2022 -> 17
            year >= 2021 -> 16
            year >= 2020 -> 15
            year >= 2019 -> 14
            year >= 2018 -> 13
            year >= 2017 -> 12
            year >= 2016 -> 11
            year >= 2015 -> 10
            year >= 2013 -> 9
            year >= 2011 -> 8
            year >= 2009 -> 7
            year >= 2007 -> 6
            year >= 2005 -> 5
            year >= 2004 -> 4
            year >= 2002 -> 3
            else -> 2
        }
    }

    private fun buildWritingTestSet(year: Int, setNum: Int, bookNum: Int): WritingTestSet {
        val setWord = when (setNum) {
            1 -> "One"
            2 -> "Two"
            3 -> "Three"
            else -> "Four"
        }

        val info = getWritingSetTemplate(year, setNum, bookNum)

        val questions = listOf(
            // Question 1: Task 1 Academic Data
            WritingQuestionItem(
                qNumber = 1,
                qNumberLabel = "Question 1",
                taskTypeLabel = "Task 1: Academic Data Report",
                topicTitle = info.q1Title,
                prompt = info.q1Prompt,
                band9Answer = info.q1Report,
                vocabularies = info.q1Vocab
            ),
            // Question 2: Task 2 Discursive Essay
            WritingQuestionItem(
                qNumber = 2,
                qNumberLabel = "Question 2",
                taskTypeLabel = "Task 2: Discursive Essay (Official Prompt)",
                topicTitle = info.q2Title,
                prompt = info.q2Prompt,
                band9Answer = info.q2Essay,
                vocabularies = info.q2Vocab
            ),
            // Question 3: Task 1 Letter / Process Flow
            WritingQuestionItem(
                qNumber = 3,
                qNumberLabel = "Question 3",
                taskTypeLabel = "Task 1: General Training / Technical Process",
                topicTitle = info.q3Title,
                prompt = info.q3Prompt,
                band9Answer = info.q3Letter,
                vocabularies = info.q3Vocab
            ),
            // Question 4: Task 2 Discussion / Problem-Solution
            WritingQuestionItem(
                qNumber = 4,
                qNumberLabel = "Question 4",
                taskTypeLabel = "Task 2: In-Depth Discussion & Evaluation",
                topicTitle = info.q4Title,
                prompt = info.q4Prompt,
                band9Answer = info.q4Essay,
                vocabularies = info.q4Vocab
            )
        )

        return WritingTestSet(
            setNumber = setNum,
            setTitle = "Set $setNum • Cambridge $bookNum Test $setWord",
            topicTheme = info.theme,
            questions = questions
        )
    }

    private fun getWritingSetTemplate(year: Int, setNum: Int, bookNum: Int): WritingSetInfo {
        // High fidelity routing for specific Cambridge books:
        if (bookNum == 19) {
            return when (setNum) {
                1 -> WritingSetInfo(
                    title = "Cambridge 19 Test 1: Social Centre Attendance & Competition vs Cooperation",
                    theme = "Cambridge 19 Test 1 • Community Engagement & Human Interaction",
                    q1Title = "Social Centre Activity Participation in Melbourne (2000–2020)",
                    q1Prompt = "The line graph provides information on the number of participants for different activities at a social centre in Melbourne, Australia, between 2000 and 2020.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                    q1Report = "The line graph illustrates the fluctuations in participant numbers across five recreational pursuits—film club, martial arts, amateur dramatics, table tennis, and musical performances—at a municipal social hub in Melbourne over a twenty-year span from 2000 to 2020.\n\nOverall, it is readily apparent that while the film club and martial arts experienced substantial upward trajectories, amateur dramatics witnessed a progressive and steep contraction in enrollment. Table tennis, after a decade of stagnation, surged noticeably in the latter period, whereas musical performances fluctuated within a narrow corridor.\n\nIn 2000, film club attendance commenced as the second most popular pursuit with roughly 64 weekly attendees, before climbing steadily to eclipse all competitors and culminate at approximately 90 participants by 2020. Similarly, martial arts attracted an increasing cohort of members, ascending from 35 participants to plateau at 75 attendees in the final year.\n\nConversely, amateur dramatics commanded the lion's share of engagement in 2000 at 70 participants, but suffered a persistent, precipitous decline, plummeting to a negligible 6 attendees by 2020. Table tennis held completely flat at 50 participants between 2000 and 2010, after which it climbed briskly to touch 54 attendees, while musical performances oscillated mildly between 10 and 18 participants throughout the surveyed duration.",
                    q1Vocab = listOf(
                        Band9Vocabulary("Upward trajectory", "Data Collocation", "Continuous rising movement", "Film club enrollment followed a consistent upward trajectory over the two decades."),
                        Band9Vocabulary("Precipitous decline", "Collocation", "Steep and sharp fall", "Participation in amateur dramatics suffered a precipitous decline toward the end of the timeline."),
                        Band9Vocabulary("Command the lion's share", "Idiomatic Phrase", "Hold the largest portion", "Dramatics initially commanded the lion's share of social centre participants."),
                        Band9Vocabulary("Oscillated mildly", "Data Lexis", "Moved gently up and down", "Musical performance attendance oscillated mildly between ten and eighteen participants.")
                    ),
                    q2Title = "Competition in Daily Life vs Collective Cooperation",
                    q2Prompt = "Some people think that competition at work, at school and in daily life is a good thing. Others believe that we should try to cooperate more, rather than competing against each other. Discuss both these views and give your own opinion. (Write at least 250 words)",
                    q2Essay = "In contemporary society, whether human progress is fundamentally catalyzed by fierce interpersonal rivalry or by harmonious collaboration represents a enduring philosophical debate. While proponents of competition argue that rivalry sharpens individual performance and fosters meritocracy, advocates of cooperation maintain that collective synergy generates superior societal outcomes. This essay examines both paradigms before contending that while healthy competition incentivizes personal ambition, structured cooperation remains the indispensable bedrock of civilizational advancement.\n\nAdvocates of competitive dynamics highlight the motivational efficacy of rivalry. In academic institutions and corporate arenas, benchmarking performance against peers compels individuals to transcend complacency, acquire cutting-edge proficiencies, and optimize output. In the commercial sphere, intense corporate rivalry fuels technological innovation, drives down consumer costs, and prevents monolithic monopolies from stagnating. Thus, competition serves as an organic sorting mechanism that rewards industriousness and analytical competence.\n\nOn the other hand, an over-emphasis on hyper-competitiveness generates corrosive societal side-effects. Relentless rivalry often breeds pervasive workplace anxiety, toxic scholastic environments, and fragmented communities where individuals perceive peers as existential adversaries rather than potential allies. Conversely, human history's greatest milestones—ranging from eradicating infectious diseases to aerospace exploration—hinge entirely upon interdisciplinary cooperation and shared knowledge. Furthermore, complex global crises such as climate mitigation require transnational solidarity rather than zero-sum competitive postures.\n\nIn conclusion, while healthy competition undeniably stimulates personal drive and prevents stagnation, unbridled rivalry erodes social cohesion. True progress is best achieved when competitive spirit is subordinated to an overarching ethos of mutual cooperation and collective enrichment.",
                    q2Vocab = listOf(
                        Band9Vocabulary("Transcend complacency", "Collocation", "Overcome laziness", "Rigorous academic competition compels students to transcend complacency."),
                        Band9Vocabulary("Corrosive side-effects", "Collocation", "Harmful damaging results", "Unchecked corporate rivalry produces corrosive side-effects on mental wellness."),
                        Band9Vocabulary("Zero-sum posture", "Economic/Game Theory Lexis", "Belief that one's win is another's loss", "Approaching environmental challenges from a zero-sum posture guarantees failure."),
                        Band9Vocabulary("Indispensable bedrock", "Metaphor", "Essential foundation", "Mutual trust serves as the indispensable bedrock of scientific breakthroughs.")
                    ),
                    q3Title = "Formal Letter: Apology for Missing a Celebration & Proposed Reunion",
                    q3Prompt = "You missed an important celebration organized by a friend. Write a letter to your friend.\n\nIn your letter:\n• Apologize sincerely for your absence\n• Explain the unforeseen circumstances that prevented your attendance\n• Suggest a specific arrangement for you both to meet and celebrate\n(Write at least 150 words)",
                    q3Letter = "Dear Liam,\n\nI am writing to express my most heartfelt apologies for being unable to attend your graduation celebration dinner last Saturday evening at the Grand Sovereign Pavilion.\n\nI had planned enthusiastically to celebrate this monumental milestone with you; however, an unforeseen family emergency arose that afternoon when my elderly grandmother suffered a sudden fall and required immediate hospitalization for orthopedic assessment. As my parents were out of the country on business, I was the sole relative available to coordinate her medical admission and remain by her bedside until she stabilized late into the night.\n\nI sincerely hope you understand the distressing situation that compelled my absence. I would love the privilege of making it up to you properly. Could we meet for dinner this coming Friday evening at The Olive Tree bistro? The evening is entirely on me so we can toast your well-deserved academic triumph in person.\n\nPlease let me know if Friday suits your schedule.\n\nWarmest regards,\nJulian",
                    q3Vocab = listOf(
                        Band9Vocabulary("Heartfelt apologies", "Collocation", "Sincere regrets", "Please accept my heartfelt apologies for the unexpected delay in my reply."),
                        Band9Vocabulary("Unforeseen circumstances", "Formal Lexis", "Unexpected events", "Due to unforeseen circumstances, the keynote address was postponed."),
                        Band9Vocabulary("Monumental milestone", "Collocation", "Huge life accomplishment", "Graduating with first-class honors is truly a monumental milestone."),
                        Band9Vocabulary("Sole relative available", "Precise Register", "Only family member present", "Being the sole relative available, he shouldered the emergency responsibilities.")
                    ),
                    q4Title = "International Tourism: Global Economic Dividends vs Cultural Erosion",
                    q4Prompt = "The benefits of international tourism far outweigh the disadvantages. To what extent do you agree or disagree with this statement? (Write at least 250 words)",
                    q4Essay = "The meteoric expansion of the global travel industry has converted tourism into a dominant driver of modern macroeconomic expansion. While detractors voice valid concerns regarding ecological degradation and the commercialization of ancestral customs, I firmly contend that the economic, infrastructural, and cross-cultural dividends of international tourism overwhelmingly surpass its associated drawbacks.\n\nFrom an economic standpoint, international tourism serves as an irreplaceable engine of regional prosperity. In developing economies and coastal provinces, tourist expenditure injects vital foreign currency into the local economy, generating millions of jobs across hospitality, culinary arts, transportation, and artisanal crafts. Moreover, tax revenues accrued from tourism enable municipal administrations to modernize foundational civic infrastructure, including international airports, water sanitation facilities, and high-speed rail corridors, which permanently elevate the living standards of resident populations.\n\nBeyond fiscal metrics, cross-border travel exerts an invaluable civilizing influence by breaking down entrenched cultural insularity. When travelers personally experience foreign lifestyles, historical monuments, and culinary customs, mutual understanding flourishes, actively dispelling xenophobic misconceptions. Although overtourism undeniably strains delicate natural ecosystems and produces transient inflationary pressure on local housing, these liabilities can be comprehensively mitigated through sustainable zoning policies, tourist quotas, and dedicated environmental remediation levies.\n\nIn conclusion, while the undesirable externalities of unregulated tourism demand proactive municipal oversight, they do not negate the profound societal benefits. International tourism fosters indispensable economic revitalization and cultural harmony, making its advantages overwhelmingly superior to its drawbacks.",
                    q4Vocab = listOf(
                        Band9Vocabulary("Macroeconomic expansion", "Economic Collocation", "Large-scale financial growth", "Tourism accounts for substantial macroeconomic expansion across island economies."),
                        Band9Vocabulary("Entrenched cultural insularity", "C2 Collocation", "Deep narrow-mindedness", "Immersive international travel dissolves entrenched cultural insularity."),
                        Band9Vocabulary("Dedicated environmental levy", "Formal Register", "Tax for nature conservation", "Imposing a dedicated environmental levy finances the protection of delicate coral reefs."),
                        Band9Vocabulary("Transient inflationary pressure", "Economic Term", "Temporary price rises", "Seasonal tourist influxes often trigger transient inflationary pressure on grocery staples.")
                    )
                )

                2 -> WritingSetInfo(
                    title = "Cambridge 19 Test 2: Gender Employment Distribution & Shorter Working Week",
                    theme = "Cambridge 19 Test 2 • Labor Markets, Working Hours & Productivity",
                    q1Title = "Gender Distribution in Diverse Industrial Sectors",
                    q1Prompt = "The bar chart compares the proportion of male and female employees in five different industrial sectors in a European country.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                    q1Report = "The comparative bar chart details the demographic distribution of male and female personnel across five distinctive employment domains—construction, manufacturing, education, healthcare, and financial services—in a European nation.\n\nOverall, it is striking that gender representation remains markedly asymmetrical across several sectors, with construction and manufacturing heavily dominated by men, whereas healthcare and education exhibit a pronounced female majority. Only the financial services sector displays approximate parity between the sexes.\n\nIn construction, male employees account for an overwhelming 88% of the workforce, leaving female participation at a minuscule 12%. A similar, albeit less extreme, disparity is evident in manufacturing, where men comprise nearly three-quarters (72%) of the staffing pool compared to 28% for women.\n\nIn sharp contrast, healthcare and education are overwhelmingly staffed by women, representing 78% and 74% of employees respectively, with male representation lagging at 22% and 26%. Financial services stands out as the most balanced sector, with female professionals holding 52% of positions compared to 48% for their male counterparts.",
                    q1Vocab = listOf(
                        Band9Vocabulary("Markedly asymmetrical", "Academic Collocation", "Extremely unequal or uneven", "Gender representation remains markedly asymmetrical across heavy technical vocations."),
                        Band9Vocabulary("Pronounced female majority", "Data Collocation", "Very clear larger group of women", "Healthcare facilities consistently exhibit a pronounced female majority in nursing."),
                        Band9Vocabulary("Minuscule participation", "Collocation", "Tiny amount of involvement", "Female involvement in mining remains at a minuscule proportion."),
                        Band9Vocabulary("Approximate parity", "Formal Lexis", "Nearly equal balance", "The financial division achieved approximate parity between male and female recruits.")
                    ),
                    q2Title = "The Shorter Working Week & Extended Weekends",
                    q2Prompt = "The working week should be shorter and workers should have a longer weekend. Do you agree or disagree? (Write at least 250 words)",
                    q2Essay = "In an era characterized by intense corporate competition and pervasive employee exhaustion, the proposal to truncate the standard five-day working week in favor of an extended three-day weekend has gained immense traction. I wholeheartedly concur with this proposition, as compressing the working week substantially elevates employee psychological well-being while simultaneously boosting macroeconomic workplace productivity.\n\nFirst and foremost, curtailing working hours serves as an urgent antidote to epidemic levels of occupational burnout. Under conventional forty-hour arrangements, professionals expend excessive cognitive energy on daily commutes and demanding shifts, leaving negligible time for restorative rest, family bonding, and physical exercise. Introducing a shorter working week affords individuals sufficient restorative downtime to recuperate their mental faculties, markedly diminishing chronic stress and absenteeism. Empirical trials conducted in Scandinavia and the UK corroborate that well-rested employees exhibit heightened morale, superior creative problem-solving, and reduced employee turnover.\n\nFurthermore, the assertion that reduced working hours automatically impairs operational output represents an obsolete industrial myth. Modern knowledge work does not scale linearly with chronological hours spent seated at a desk; rather, fatigue invariably induces diminished marginal returns, procrastination, and administrative errors. When working weeks are condensed, companies are compelled to streamline inefficient assemblies, eliminate redundant meetings, and harness automation tools. Consequently, focused employees accomplish identical or superior throughput within thirty-two hours, disproving the necessity of long hours.\n\nIn conclusion, transitioning toward a shorter working week with an extended weekend represents a progressive and mutually beneficial reform. It revitalizes individual health and work-life balance while optimizing institutional productivity.",
                    q2Vocab = listOf(
                        Band9Vocabulary("Pervasive exhaustion", "Collocation", "Widespread deep tiredness", "Pervasive exhaustion among healthcare professionals compromises clinical accuracy."),
                        Band9Vocabulary("Diminishing marginal returns", "Economic Principle", "Less benefit for extra effort", "Working beyond eight consecutive hours generates diminishing marginal returns."),
                        Band9Vocabulary("Restorative downtime", "Collocation", "Rest that heals and recharges", "Adequate restorative downtime is essential for cognitive synthesis and peak performance."),
                        Band9Vocabulary("Obsolete industrial myth", "Critical Lexis", "Outdated wrong belief", "Equating physical desk presence with actual value creation is an obsolete industrial myth.")
                    ),
                    q3Title = "Formal Letter: Inquiry Regarding Temporary Accommodation",
                    q3Prompt = "You are relocating to another city for work and require temporary furnished accommodation. Write a letter to a local real estate agent.\n\nIn your letter:\n• State your planned arrival date and intended duration of tenancy\n• Specify your accommodation preferences and budget constraints\n• Inquire about viewing arrangements and lease terms\n(Write at least 150 words)",
                    q3Letter = "Dear Mr. Gallagher,\n\nI am writing to formally request your assistance in securing temporary furnished accommodation in Manchester, ahead of my upcoming professional relocation.\n\nI have recently accepted the position of Senior Financial Analyst with Barclays Capital, and I am scheduled to commence duties on the 1st of next month. Consequently, I require a well-maintained one-bedroom or executive studio apartment for an initial tenure of six months, with the potential option to transition into a rolling annual lease depending on project extensions.\n\nRegarding my criteria, I would prefer a modern apartment situated within walking distance of the central business district or adjacent to a primary Metrolink station. The property must be fully furnished with high-speed broadband provisions and a dedicated workstation. My allocated housing stipend comfortably accommodates a rental ceiling of up to £1,400 per calendar month, inclusive of municipal council tax and water charges.\n\nCould you kindly forward details of currently available listings and outline the documentation required for tenancy screening?\n\nYours sincerely,\nNathaniel Drake",
                    q3Vocab = listOf(
                        Band9Vocabulary("Tenure of tenancy", "Formal Legal Lexis", "Length of apartment rental", "The lease agreement outlines an initial tenure of twelve calendar months."),
                        Band9Vocabulary("Housing stipend", "Collocation", "Company allowance for rent", "The corporate relocation package provides a generous monthly housing stipend."),
                        Band9Vocabulary("Adjacent to transit", "Collocation", "Next to public transport", "Selecting an apartment adjacent to the underground railway eliminates commute stress."),
                        Band9Vocabulary("Tenancy screening", "Formal Term", "Checking background of renter", "Prospective applicants must submit bank statements for standard tenancy screening.")
                    ),
                    q4Title = "Erosion of Communal Dining vs Modern Fast Food Habits",
                    q4Prompt = "In many nations, traditional family meals are being replaced by fast food and solitary snacking. What are the causes of this change, and what effects does it have on family life and health? (Write at least 250 words)",
                    q4Essay = "In modern post-industrial societies, the time-honored tradition of family members congregating around a shared dinner table is undergoing rapid erosion, steadily displaced by convenient fast food and solitary snacking. This shift stems primarily from the frantic pace of contemporary corporate lifestyles and the proliferation of digital entertainment. This essay will examine these root causes before highlighting the severe detriments this trend poses to family cohesion and public health.\n\nThe foremost driver of this culinary transformation is the relentless intensity of modern working schedules. In dual-income households, parents frequently endure grueling commutes and unpredictable overtime, leaving neither the chronological bandwidth nor the physical stamina required to prepare elaborate meals from scratch. Consequently, pre-packaged convenience meals and on-demand delivery apps emerge as indispensable time-saving expedients. Furthermore, the ubiquity of personalized smart screens has fragmented family leisure, encouraging individuals to consume meals in isolation while absorbed in their personal digital feeds.\n\nThe ramifications of this trend are overwhelmingly deleterious. Domestically, abandoning communal dining dissolves the principal forum through which family members exchange emotional support, transmit ancestral wisdom, and monitor adolescent well-being. A dinner table once acted as a social adhesive; without it, familial relationships frequently grow distant and transactional. Physically, reliance on ultra-processed takeout laden with refined sugars, trans-fats, and synthetic preservatives directly drives escalating rates of childhood obesity, hypertension, and cardiovascular disorders.\n\nIn conclusion, the demise of traditional family dining is fueled by hectic working hours and digital isolation. To avert the twin crises of social alienation and metabolic disease, families must deliberately reclaim the dinner table as an uncompromisable sanctuary for nourishment and connection.",
                    q4Vocab = listOf(
                        Band9Vocabulary("Deleterious ramifications", "Collocation", "Harmful consequences", "Sedentary living and processed food inflict deleterious ramifications on national health."),
                        Band9Vocabulary("Social adhesive", "Sociological Metaphor", "Thing that binds people together", "Communal dining traditions serve as an invaluable social adhesive for communities."),
                        Band9Vocabulary("Chronological bandwidth", "Academic Lexis", "Time available in schedule", "Exhausting corporate shifts leave working parents with minimal chronological bandwidth."),
                        Band9Vocabulary("Uncompromisable sanctuary", "Literary Collocation", "Safe place that cannot be traded", "The home dinner table should remain an uncompromisable sanctuary for genuine dialogue.")
                    )
                )

                3 -> WritingSetInfo(
                    title = "Cambridge 19 Test 3: Tech Ownership & Compulsory Savings for Youth",
                    theme = "Cambridge 19 Test 3 • Financial Prudence & Household Technology",
                    q1Title = "Digital Infrastructure & Tech Ownership Across Four Nations",
                    q1Prompt = "The table shows the percentages of households with internet access, mobile phone subscriptions, and desktop computers in four countries.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                    q1Report = "The comparative table details demographic access rates across three primary digital tools—broadband internet connections, mobile phone subscriptions, and personal desktop computers—within four distinct nations (Country A, B, C, and D).\n\nOverall, mobile phone subscriptions universally represent the most widespread technological asset across all surveyed jurisdictions, consistently outpacing computer and internet adoption. Furthermore, Country A and Country B demonstrate significantly higher integration across all digital categories compared to Countries C and D.\n\nIn Country A and Country B, mobile telephone coverage has attained near-saturation at 96% and 94% respectively. Concurrently, internet penetration in Country A stands at a formidable 89%, marginally eclipsing Country B's 85%, while domestic computer ownership registers 78% in both territories.\n\nIn contrast, technological infrastructure in Country C and Country D exhibits noticeable lag. While mobile subscriptions remain relatively robust at 82% in Country C and 74% in Country D, household internet connectivity plunges to 56% and 42% respectively. Desktop computer availability records the lowest prevalence of all, touching just 45% in Country C and a modest 33% in Country D.",
                    q1Vocab = listOf(
                        Band9Vocabulary("Attained near-saturation", "Collocation", "Almost 100% full market reach", "Smartphone adoption has attained near-saturation among urban consumers."),
                        Band9Vocabulary("Universally represent", "Formal Collocation", "Always act as everywhere", "Mobile subscriptions universally represent the primary gateway to online commerce."),
                        Band9Vocabulary("Noticeable lag", "Collocation", "Clear delay or backwardness", "Rural broadband networks exhibit a noticeable lag compared to metropolitan centers."),
                        Band9Vocabulary("Marginally eclipsing", "Data Lexis", "Beating by a tiny amount", "Country A led the table, marginally eclipsing its neighbors by two percentage points.")
                    ),
                    q2Title = "Compulsory Financial Savings & Youth Prudence",
                    q2Prompt = "It is important for everyone, including young people, to save money for their future. To what extent do you agree or disagree with this statement? (Write at least 250 words)",
                    q2Essay = "In the contemporary macroeconomic climate characterized by volatile employment markets, inflationary spirals, and diminishing state pension assurances, the imperative for financial foresight has never been more urgent. I wholeheartedly agree that cultivating disciplined savings habits from an early age is a indispensable life skill that shields individuals from systemic economic vulnerabilities.\n\nPrimarily, instilling financial prudence in young adults provides a critical buffer against unforeseen personal catastrophes. Life in the modern world is rife with economic turbulence, ranging from sudden medical emergencies to unexpected layoffs amidst industrial automation. When young workers routinely squirrel away a portion of their earnings into emergency liquidity reserves, they insulate themselves from crippling high-interest credit card debt and predatory loans. Furthermore, early savings exploit the mathematical wonder of compound interest; even modest capital invested during one's twenties yields astronomical returns across four decades, ensuring dignified financial autonomy in retirement.\n\nMoreover, the discipline required to maintain consistent savings imparts vital psychological maturity and temperance. In a hyper-consumerist culture inundated with targeted digital advertisements urging instant gratification, learning to delay impulsive purchases fosters emotional resilience and strategic planning. Young individuals who master budgeting are substantially more capable of financing transformative long-term investments, such as pursuing advanced postgraduate credentials, purchasing real estate, or launching entrepreneurial startups without being hamstrung by venture debts.\n\nIn conclusion, advocating that everyone, especially youth, prioritize financial savings is not merely sound fiscal advice; it is a foundational prerequisite for enduring personal liberty and macroeconomic resilience.",
                    q2Vocab = listOf(
                        Band9Vocabulary("Financial foresight", "Collocation", "Planning money for the future", "Failing to exercise financial foresight exposes households to severe debt."),
                        Band9Vocabulary("Compound interest", "Economic Term", "Interest earned on interest", "Harnessing the exponential power of compound interest guarantees long-term wealth."),
                        Band9Vocabulary("Instant gratification", "Psychological Lexis", "Needing pleasure right away", "Aggressive social media ads exploit youthful cravings for instant gratification."),
                        Band9Vocabulary("Hamstrung by debts", "Idiomatic Phrase", "Severely restricted by owing money", "Ambitious graduates are frequently hamstrung by predatory student loan debts.")
                    ),
                    q3Title = "Formal Letter: Request for Refund/Replacement of Defective Goods",
                    q3Prompt = "You recently bought an expensive electronic item online that arrived defective. Write a formal complaint letter to the customer support manager.\n\nIn your letter:\n• Provide order identification details and describe the defect\n• Detail your previous failed attempts to resolve the issue with telephone support\n• State the specific remediation you require (replacement or full refund)\n(Write at least 150 words)",
                    q3Letter = "Dear Customer Support Manager,\n\nI am writing to register an urgent formal complaint regarding an unsatisfactory transaction concerning order reference #UK-98421, placed via your flagship online portal on the 12th of this month.\n\nThe consignment, comprising an Apex Pro Ultra-HD 34-inch Monitor valued at £680, was delivered to my residence yesterday afternoon. However, upon unboxing and connecting the peripheral to my workstation, I discovered that the internal LED display panel is severely damaged, exhibiting persistent vertical green scan lines and intermittent flickering that render the screen utterly unusable.\n\nI contacted your telephone helpline immediately; however, the representative dismissed my concerns, attributing the malfunction to courier mishandling and refusing to authorize an exchange without a protracted two-week diagnostic review. Given that the merchandise was defective upon delivery, this response constitutes a clear breach of your statutory obligations under consumer protection legislation.\n\nI request an immediate courier collection of the damaged unit and the prompt dispatch of a verified replacement, or failing that, an immediate full refund to my original payment card.\n\nYours faithfully,\nArthur Pendelton",
                    q3Vocab = listOf(
                        Band9Vocabulary("Protracted review", "Collocation", "Unnecessarily long investigation", "I cannot accept a protracted diagnostic review for an item damaged upon delivery."),
                        Band9Vocabulary("Statutory obligations", "Formal Legal Lexis", "Duties mandated by law", "Retailers must uphold their statutory obligations under consumer rights statutes."),
                        Band9Vocabulary("Utterly unusable", "Collocation", "Completely broken or useless", "The severe display flickering rendered the expensive monitor utterly unusable."),
                        Band9Vocabulary("Prompt dispatch", "Collocation", "Fast sending of package", "I demand the prompt dispatch of an undamaged replacement monitor.")
                    ),
                    q4Title = "Tertiary Curricula: Pure Market Utility vs Liberal Arts",
                    q4Prompt = "Some people believe that universities should only offer courses that directly lead to employment, while others argue that subjects like philosophy and history should also be funded. Discuss both views and give your opinion. (Write at least 250 words)",
                    q4Essay = "The ultimate mission of higher education remains a subject of contentious discourse among policymakers and academics. While utilitarian pragmatists argue that universities should exclusively subsidize vocational degrees that satisfy immediate industrial labor demands, champions of the liberal arts maintain that humanities disciplines are vital to civilizational wisdom. This essay examines both perspectives before contending that a premier tertiary ecosystem must preserve humanities alongside STEM programs.\n\nOn the one hand, advocates of strictly employment-oriented curricula emphasize macroeconomic realities. In developing and developed nations alike, public revenues invested into tertiary education are expected to generate measurable economic returns. Degrees in software engineering, biotechnology, and accounting directly alleviate skilled labor shortages, driving industrial innovation and bolstering national tax receipts. Expecting taxpayers to subsidize obscure degrees that yield modest employment prospects risks producing debt-laden graduates who struggle with structural underemployment.\n\nOn the other hand, reducing universities to mere vocational training centers betrays the historic purpose of the academy. Disciplines such as philosophy, history, and literature do not merely teach static facts; they cultivate rigorous ethical discernment, nuanced textual analysis, and historical perspective. In an era increasingly dominated by algorithmic decision-making and rapid socio-political disruption, society desperately requires ethical philosophers to govern artificial intelligence and historians to prevent catastrophic geopolitical repetitions. A society devoid of humanistic inquiry risks becoming technologically advanced yet morally bankrupt.\n\nIn conclusion, while aligning tertiary programs with workforce demands is sensible, eliminating liberal arts education is dangerously short-sighted. True higher education must balance pragmatic vocational utility with the philosophical inquiry that enriches the human spirit.",
                    q4Vocab = listOf(
                        Band9Vocabulary("Utilitarian pragmatists", "Academic Lexis", "People caring only about practical use", "Utilitarian pragmatists judge educational value purely by graduate starting salaries."),
                        Band9Vocabulary("Structural underemployment", "Economic Lexis", "Working below one's skills", "Over-saturating certain disciplines precipitates severe structural underemployment."),
                        Band9Vocabulary("Ethical discernment", "Collocation", "Ability to judge right and wrong", "Governing autonomous systems demands sophisticated ethical discernment."),
                        Band9Vocabulary("Morally bankrupt", "Collocation", "Completely devoid of morals", "Technological supremacy without humanistic empathy produces a morally bankrupt civilization.")
                    )
                )

                else -> WritingSetInfo(
                    title = "Cambridge 19 Test 4: Global Supermarket Food Imports & Living Alone",
                    theme = "Cambridge 19 Test 4 • Globalization, Food Logistics & Urban Households",
                    q1Title = "National Electricity Generation Fuel Proportions (1990 vs 2020)",
                    q1Prompt = "The two pie charts illustrate the proportions of electricity generated by different fuel sources in a particular nation in 1990 and 2020.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                    q1Report = "The comparative pie charts detail the reconfiguration of electricity generation sources in a specific country between 1990 and 2020, categorizing supply across coal, natural gas, nuclear power, and renewable alternatives.\n\nOverall, the thirty-year duration witnessed a dramatic decarbonization transition, characterized by the precipitous decline of coal and the unprecedented expansion of renewable energy generation. Natural gas maintained a pivotal bridging role throughout, while nuclear power experienced a modest contraction.\n\nIn 1990, coal dominated the national energy portfolio, accounting for a massive 62% of all power output. Natural gas represented the second most significant source at 21%, followed by nuclear power at 13%, while renewable energy occupied a negligible 4% fraction of the total.\n\nBy 2020, the energy landscape was fundamentally transformed. Coal generation plummeted to a minor 14%, being decisively supplanted by renewable technologies, which surged eightfold to command 34% of national generation. Concurrently, natural gas expanded slightly to 38%, cementing its position as the single largest individual fuel, while nuclear energy declined to 14%.",
                    q1Vocab = listOf(
                        Band9Vocabulary("Decarbonization transition", "Collocation", "Shift away from fossil fuels", "The nation embarked on an aggressive decarbonization transition over thirty years."),
                        Band9Vocabulary("Decisively supplanted", "Collocation", "Completely replaced by superior force", "Legacy coal generators were decisively supplanted by offshore wind arrays."),
                        Band9Vocabulary("Energy portfolio", "Collocation", "Mix of energy sources", "Diversifying the national energy portfolio guarantees electrical grid stability."),
                        Band9Vocabulary("Precipitous decline", "Collocation", "Very steep fall", "Coal consumption witnessed a precipitous decline across modern power grids.")
                    ),
                    q2Title = "Global Supermarkets: Worldwide Food Imports",
                    q2Prompt = "In many countries nowadays, consumers can go to a supermarket and buy food produced all over the world. Do you think this is a positive or negative development? (Write at least 250 words)",
                    q2Essay = "The ubiquity of globalized supply chains has fundamentally transformed modern retail, enabling supermarkets to stock fresh exotic produce, dairy, and seafood sourced from across continents year-round. While detractors argue that international food transit exerts severe environmental tolls, I maintain that this development is overwhelmingly positive, delivering immense nutritional variety, culinary enrichment, and vital agricultural export income to developing economies.\n\nThe principal benefit of international food distribution is the dramatic elevation in dietary diversity and nutritional security. In temperate and sub-polar nations, domestic agricultural seasons are geographically truncated, historically leaving citizens dependent on preserved root crops during freezing winter months. Today, global supply corridors ensure constant availability of fresh vitamin-rich citrus, leafy greens, and exotic fruits regardless of local seasonal limitations. Furthermore, access to international ingredients enriches multicultural culinary traditions, fostering cultural literacy and gastronomic creativity in households worldwide.\n\nMoreover, the global agrarian trade acts as a powerful catalyst for poverty alleviation across emerging economies. Developing nations in the Global South possess optimal climatic conditions for cultivating high-demand commodities such as coffee, cacao, avocados, and quinoa. By exporting these agricultural yields to affluent consumer markets, smallholder farmers and agrarian co-operatives generate substantial export revenues, elevating rural living standards and financing local healthcare and educational facilities. Although food miles contribute to carbon emissions, advancing maritime logistics and green shipping technologies are actively mitigating these environmental footprints.\n\nIn conclusion, the availability of globally sourced groceries in modern supermarkets is a profoundly positive phenomenon. It bolsters consumer dietary well-being while fueling inclusive global economic development.",
                    q2Vocab = listOf(
                        Band9Vocabulary("Nutritional security", "Collocation", "Reliable access to healthy food", "Global agricultural corridors guarantee domestic nutritional security throughout winter."),
                        Band9Vocabulary("Poverty alleviation", "Formal Lexis", "Reducing poverty", "Fair-trade agricultural exports play a transformative role in rural poverty alleviation."),
                        Band9Vocabulary("Agrarian co-operatives", "Academic Lexis", "Farmer-owned business groups", "Joining agrarian co-operatives empowers smallholders to negotiate equitable commodity prices."),
                        Band9Vocabulary("Geographically truncated", "Formal Register", "Cut short by geography", "Agricultural yields in northern territories remain geographically truncated by severe frost.")
                    ),
                    q3Title = "Formal Letter: Request for Neighborhood Park Renovation",
                    q3Prompt = "Write a letter to your local municipal council requesting improvements to the recreational facilities in your community park.\n\nIn your letter:\n• Explain the current condition and deficiencies of the park\n• Propose specific upgrades (e.g. playground equipment, lighting, green landscaping)\n• Detail how these improvements will benefit the local community\n(Write at least 150 words)",
                    q3Letter = "Dear Members of the Municipal Planning Board,\n\nI am writing on behalf of the residents of the Oakwood precinct to respectfully request an urgent capital allocation to renovate our neighborhood recreational park, situated on Elmwood Avenue.\n\nWhile this public space was once the vibrant epicenter of communal recreation, it has suffered noticeable neglect over the past five years. The children's playground equipment is rusted and unsafe, platform benches are vandalized, and the perimeter lacks adequate nocturnal illumination, creating severe safety concerns that deter families from utilizing the grounds after dusk.\n\nWe propose three concrete enhancements: firstly, replacing the dilapidated apparatus with modern, certified inclusive playground structures; secondly, installing solar-powered LED streetlights along the primary footpaths; and thirdly, planting native flowering flora alongside a dedicated perimeter jogging circuit.\n\nRevitalizing this green lung will foster physical exercise, reduce adolescent antisocial behavior, and reconstruct a cohesive sense of civic pride across our demographic.\n\nYours faithfully,\nClara Townsend",
                    q3Vocab = listOf(
                        Band9Vocabulary("Vibrant epicenter", "Collocation", "Lively central hub", "The central plaza serves as the vibrant epicenter of weekend cultural life."),
                        Band9Vocabulary("Nocturnal illumination", "Formal Lexis", "Lighting during the night", "Installing nocturnal illumination dramatically enhances pedestrian safety after dark."),
                        Band9Vocabulary("Dilapidated apparatus", "Formal Term", "Broken old equipment", "Council officials promptly removed the dilapidated apparatus from the playground."),
                        Band9Vocabulary("Cohesive sense of civic pride", "Collocation", "Strong shared local pride", "Community volunteering fosters a cohesive sense of civic pride among neighbors.")
                    ),
                    q4Title = "The Rise of Single-Person Households",
                    q4Prompt = "In some countries, more and more people choose to live alone rather than with family or partners. Do the advantages of this trend outweigh the disadvantages? (Write at least 250 words)",
                    q4Essay = "In numerous industrialized nations, societal and economic shifts have propelled an unprecedented surge in single-person households. While critics argue that solo living fosters emotional isolation and strains residential housing availability, I maintain that the personal autonomy, financial empowerment, and psychological maturity conferred by independent living ensure that its advantages outweigh its drawbacks.\n\nThe foremost merit of living alone is the unparalleled degree of personal autonomy and self-determination it affords. Free from the interpersonal compromises and domestic friction inherent in shared living arrangements, individuals exercise complete governance over their domestic environment, schedule, and expenditure. For career-driven professionals, this unfettered tranquility provides an optimal sanctum for deep intellectual focus, flexible working schedules, and personal creative pursuits. Furthermore, managing an independent dwelling compels individuals to cultivate comprehensive self-reliance, mastering budgeting, culinary sustenance, and logistical problem-solving without emotional crutches.\n\nConversely, detractors contend that solitary domesticity accelerates societal fragmentation and escalates living expenses. Without question, living unaccompanied requires higher per-capita expenditures on rent, heating, and utilities, while lacking the built-in companionship that buffers against chronic loneliness. However, solo living does not equate to social hermeticism. Modern urbanites actively satisfy their communal needs through vibrant external networks—frequenting athletic clubs, cultural associations, and shared co-working spaces—thereby cultivating deliberate, high-quality friendships without the domestic claustrophobia of cohabitation.\n\nIn conclusion, while single-person living presents financial and emotional hurdles, they are readily navigated through active social participation. The profound self-reliance and intellectual freedom it nurtures make it an overwhelmingly empowering trend for modern adults.",
                    q4Vocab = listOf(
                        Band9Vocabulary("Unfettered tranquility", "Collocation", "Complete peaceful freedom", "Living alone provides unfettered tranquility for intense scholarly research."),
                        Band9Vocabulary("Social hermeticism", "C2 Lexis", "Complete isolation from people", "Solo living should never be conflated with involuntary social hermeticism."),
                        Band9Vocabulary("Domestic claustrophobia", "Metaphor", "Feeling suffocated at home", "Sharing cramped quarters often generates severe domestic claustrophobia among roommates."),
                        Band9Vocabulary("Emotional crutches", "Idiomatic Phrase", "Over-relying on others", "Thriving independently forces youth to abandon emotional crutches and mature.")
                    )
                )
            }
        }

        // Default handler for all other Cambridge books:
        return when (setNum) {
            1 -> WritingSetInfo(
                title = "Cambridge $bookNum Test 1: Industrial Trends & Scientific Objectives",
                theme = "Cambridge $bookNum Test 1 • Science, Industrial Data & Societal Progress",
                q1Title = "Global Industrial Output & Renewable Energy Allocation (Cambridge $bookNum)",
                q1Prompt = "The line chart illustrates public and private sector investments (in billions of dollars) across renewable energy, manufacturing, and technology across a twenty-year timeframe.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                q1Report = "The line graph delineates capital allocation across three discrete economic sectors—renewable energy, digital technology, and traditional manufacturing—spanning a twenty-year period.\n\nOverall, it is readily apparent that while expenditure in legacy manufacturing experienced a progressive contraction over the timeframe, investments in digital technology and clean energy exhibited an exponential upward trajectory, with technology emerging as the dominant recipient of fiscal resources.\n\nInitially, traditional manufacturing commanded the lion's share of financial capital at approximately $120 billion, dwarfing renewable power ($30 billion) and technology ($10 billion). However, manufacturing expenditure witnessed a precipitous decline over subsequent intervals, plummeting to a modest plateau of $45 billion by the final year.\n\nConversely, capital channelled into digital technology accelerated dramatically, eclipsing conventional industries around the mid-point of the timeline before culminating in a record high of $210 billion. Concurrently, renewable energy outlays climbed steadily to attain $165 billion, underscoring a synchronized shift toward next-generation technological infrastructure.",
                q1Vocab = listOf(
                    Band9Vocabulary("Exponential upward trajectory", "Data Collocation", "Rapid continuous increase", "Investments followed an exponential upward trajectory over the observed timeframe."),
                    Band9Vocabulary("Command the lion's share", "Idiomatic Phrase", "Hold the largest portion", "Heavy industries initially commanded the lion's share of regional investment."),
                    Band9Vocabulary("Precipitous decline", "Collocation", "Steep and sharp fall", "Output suffered a precipitous decline following the enforcement of emissions caps."),
                    Band9Vocabulary("Synchronized shift", "Collocation", "Coordinated change", "The data illustrates a synchronized shift toward sustainable power infrastructure.")
                ),
                q2Title = "The Primary Aim of Science: Improving Human Lives",
                q2Prompt = "The most important aim of science should be to improve people's lives. To what extent do you agree or disagree with this statement? (Write at least 250 words)",
                q2Essay = "Throughout human history, scientific discovery has served as the vanguard of material progress. While some pure theoretical scientists argue that inquiry should be pursued purely for the expansion of knowledge without utilitarian constraints, I firmly believe that the paramount aim of scientific endeavor must be the tangible improvement of human well-being and planetary health.\n\nFirst and foremost, science is supported by public wealth, and its ethical legitimacy stems from its capacity to alleviate universal human suffering. When scientific talent is directed toward public healthcare, the eradication of debilitating pathologies, and agricultural optimization, the societal returns are immense. For instance, the synthesis of antibiotics, mRNA vaccines, and water desalinization plants has saved hundreds of millions of lives, elevating median longevity across continents. Divorcing scientific funding from the urgent needs of humanity risks fostering self-indulgent research that ignores pressing humanitarian crises.\n\nFurthermore, scientific breakthroughs that disregard human welfare frequently lead to catastrophic civilizational hazards. History provides chilling examples of scientific acumen weaponized for destructive purposes, from thermonuclear warheads to predatory chemical defoliants. When scientific ambition is governed without a foundational moral commitment to human betterment, research inevitably degenerates into instruments of oppression. Therefore, requiring that scientific inquiry prioritize life preservation, ecological remediation, and poverty reduction establishes an indispensable ethical compass.\n\nIn conclusion, while the pursuit of theoretical knowledge for its own sake possesses undeniable intellectual charm, it must remain subordinate to human welfare. The noblest and most essential mandate of science is to elevate the quality of human life and safeguard our collective future.",
                q2Vocab = listOf(
                    Band9Vocabulary("Vanguard of material progress", "Metaphor", "Leading edge of improvement", "Scientific research remains the vanguard of material progress in modern medicine."),
                    Band9Vocabulary("Tangible improvement", "Collocation", "Real measurable positive change", "Applied research must translate into tangible improvement for ordinary citizens."),
                    Band9Vocabulary("Indispensable ethical compass", "Metaphor", "Crucial moral guide", "Social responsibility serves as an indispensable ethical compass for genetic engineering."),
                    Band9Vocabulary("Debilitating pathologies", "Medical Formal Lexis", "Paralyzing diseases", "Developing cures for debilitating pathologies must remain a priority for national laboratories.")
                ),
                q3Title = "Formal Letter: Request for Remote Research Authorization",
                q3Prompt = "You wish to transition to a flexible or hybrid working schedule to undertake advanced postgraduate research. Write a formal letter to your department director.\n\nIn your letter:\n• State the purpose of your letter and your proposed schedule\n• Highlight your past achievements within the organization\n• Explain how the enterprise will benefit from your advanced study\n(Write at least 150 words)",
                q3Letter = "Dear Director Richardson,\n\nI am writing to formally submit a proposal requesting authorization to transition my operational schedule into a hybrid arrangement, effective from the start of next quarter.\n\nDuring my five-year tenure within the strategic analysis team, I have consistently exceeded our quarterly performance metrics, most recently directing the client portfolio restructuring that delivered a sixteen percent increase in departmental revenue. Under my proposed arrangement, I intend to execute focused data modeling remotely on Mondays, Wednesdays, and Fridays, while remaining on-site for stakeholder assemblies on Tuesdays and Thursdays.\n\nThis structural flexibility will enable me to balance advanced doctoral research in predictive algorithms with my corporate responsibilities. Crucially, integrating cutting-edge machine learning methodologies directly into our internal analytics pipeline will significantly elevate our market competitiveness, providing the department with proprietary predictive models at zero additional consulting overhead.\n\nI welcome the opportunity to discuss this proposal at your earliest convenience.\n\nYours sincerely,\nMarcus Vance",
                q3Vocab = listOf(
                    Band9Vocabulary("Tenure within the team", "Formal Collocation", "Time working in department", "Throughout my tenure within the team, I have maintained meticulous standards."),
                    Band9Vocabulary("Proprietary predictive models", "Collocation", "Private forecasting algorithms", "Developing proprietary predictive models delivers a decisive competitive advantage."),
                    Band9Vocabulary("Structural flexibility", "Collocation", "Adaptive working terms", "Offering structural flexibility markedly reduces staff turnover among senior analysts."),
                    Band9Vocabulary("At your earliest convenience", "Formal Signoff", "As soon as you are available", "I would be grateful to meet at your earliest convenience.")
                ),
                q4Title = "Rural-to-Urban Migration: Depopulation of the Countryside",
                q4Prompt = "In many countries around the world, rural people are moving to cities, so the population in the countryside is decreasing. Do you think this is a positive or a negative development? (Write at least 250 words)",
                q4Essay = "The mass demographic exodus from agricultural hamlets into bustling metropolitan centers constitutes one of the defining demographic phenomena of modern times. While urbanization is often hailed as a sign of industrial development, I strongly contend that the relentless depopulation of the countryside is an overwhelmingly negative trend that destabilizes national economies and erodes cultural heritage.\n\nAt the forefront of the perils associated with rural desertion is the catastrophic threat to food security and agricultural resilience. When energetic young generations abandon farming provinces to seek corporate white-collar roles, rural territories face critical labor shortages in agriculture and horticulture. This demographic aging of farming communities forces nations to depend heavily on costly imported food supplies, undermining national sovereignty during international geopolitical crises. Furthermore, when ancestral villages are abandoned, centuries of indigenous ecological wisdom, craftsmanship, and linguistic heritage vanish irrevocably.\n\nSimultaneously, the hyper-concentration of populations into mega-cities triggers chronic infrastructural collapse in urban environments. Capital cities around the globe struggle with severe housing deficits, skyrocketing rental prices, gridlocked transport arteries, and overwhelming strain on public hospitals and schools. Rather than finding prosperity, impoverished rural migrants frequently end up trapped in precarious peripheral informal settlements. Redressing this imbalance demands aggressive regional investment: governments must establish specialized universities, agricultural subsidies, and modern high-speed broadband in rural provinces to make regional living commercially and socially attractive.\n\nIn conclusion, the uncontrolled flight from the countryside into metropolitan capitals is an alarming trend. It leaves megacities congested and fragile while threatening agricultural security and cultural continuity.",
                q4Vocab = listOf(
                    Band9Vocabulary("Mass demographic exodus", "Collocation", "Huge movement of people", "The mass demographic exodus has left rural agricultural zones critically underpopulated."),
                    Band9Vocabulary("Food security and resilience", "Collocation", "Safe and steady food supply", "Maintaining young farming communities is essential to guarantee long-term food security."),
                    Band9Vocabulary("Precipitate infrastructural collapse", "Formal Register", "Cause public services to fail", "Uncontrolled urban migration threatens to precipitate infrastructural collapse in capital cities."),
                    Band9Vocabulary("Informal settlements", "Urban Planning Term", "Slums and shantytowns", "Migrants unable to afford exorbitant rents are forced into precarious informal settlements.")
                )
            )

            2 -> WritingSetInfo(
                title = "Cambridge $bookNum Test 2: Academic Specialization vs Holistic Learning",
                theme = "Cambridge $bookNum Test 2 • Higher Education & Specialized Knowledge",
                q1Title = "University Enrolment vs Employment Integration (Cambridge $bookNum)",
                q1Prompt = "The bar graph depicts the percentage of university graduates entering professional employment within six months of graduation across four academic faculties.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                q1Report = "The comparative bar chart presents graduate professional integration rates within a six-month post-qualification window across four distinctive faculties—STEM disciplines, Healthcare, Humanities, and Vocational Trades.\n\nAcross the historical survey, Healthcare and Vocational graduates consistently achieved the most resilient employment outcomes, whereas Humanities alumni encountered noticeable volatility and an overarching downward trend.\n\nIn the initial year, Healthcare led with an exceptional 92% employment rate, closely trailed by STEM graduates at 88%, while Humanities and Vocational Trades recorded 74% and 79% respectively. Over the subsequent decade, while Healthcare held near-universal absorption at roughly 95%, Vocational Trades accelerated remarkably to touch 93%, underpinned by surging demand for specialized technical competencies.\n\nIn stark contrast, employment absorption for Humanities graduates deteriorated markedly, descending to 58%. STEM disciplines, despite experiencing brief fluctuations during macroeconomic downturns, maintained strong market appeal, concluding the period at 86%, confirming the premium employers place upon quantitative and technical credentials.",
                q1Vocab = listOf(
                    Band9Vocabulary("Resilient employment outcomes", "Collocation", "Stable job success", "Applied engineering apprentices secured remarkably resilient employment outcomes."),
                    Band9Vocabulary("Overarching downward trend", "Data Lexis", "General falling pattern", "Humanities graduate absorption exhibited an overarching downward trend."),
                    Band9Vocabulary("Near-universal absorption", "Collocation", "Almost 100% hiring rate", "Specialized medical faculties achieved near-universal absorption within six months."),
                    Band9Vocabulary("Underpinned by surging demand", "Idiomatic Linker", "Supported by strong need", "Trade wages surged, underpinned by surging demand for renewable infrastructure technicians.")
                ),
                q2Title = "Single Subject Specialization vs Multidisciplinary Breadth",
                q2Prompt = "Some university students want to learn about other subjects in addition to their main subjects. Others believe it is more important to give all their time and attention to studying for a qualification. Discuss both these views and give your opinion. (Write at least 250 words)",
                q2Essay = "In tertiary academia, the conflict between deep curricular specialization and multidisciplinary exploration is a topic of intense pedagogical debate. While traditionalists argue that intense focus on a single discipline is essential to attain professional mastery, advocates of broader learning maintain that interdisciplinary literacy is indispensable in a modern interconnected world. This essay analyzes both stances before asserting that blending core specialization with elective interdisciplinary study produces the most capable graduates.\n\nAdvocates of single-subject specialization emphasize the uncompromising depth demanded by modern technical vocations. Fields such as aerospace engineering, molecular biology, and neurosurgery require exhaustive mastery of complex theoretical doctrine and empirical laboratory skills. Diverting valuable study hours into unrelated humanities or generalist courses risks diluting technical rigor, leaving students underprepared for high-stakes certification examinations. Furthermore, in competitive corporate recruitment, candidates with specialized, concentrated credentials frequently hold a decisive edge over generalists.\n\nConversely, excessive academic hyper-specialization often produces graduates with insular perspectives who struggle when confronted with multidisciplinary challenges. In contemporary economies, the most revolutionary innovations occur precisely at the intersection of disparate fields: artificial intelligence requires philosophy and linguistics for natural language understanding; environmental engineering demands economics and public policy to design enforceable carbon solutions. Students exposed to diverse fields cultivate agile creative synthesis, superior communication skills, and cognitive flexibility, enabling them to pivot seamlessly across evolving career landscapes.\n\nIn conclusion, while achieving profound mastery in one's core subject is non-negotiable, total academic myopia is a dangerous handicap. The ideal university curriculum provides rigorous single-subject specialization while encouraging complementary multidisciplinary coursework.",
                q2Vocab = listOf(
                    Band9Vocabulary("Disparate fields", "Academic Lexis", "Completely different subjects", "Breakthrough innovations routinely emerge at the intersection of disparate fields."),
                    Band9Vocabulary("Academic myopia", "Critical Metaphor", "Short-sighted single focus", "Rigid specialization risks trapping students in academic myopia."),
                    Band9Vocabulary("Cognitive flexibility", "Psychological Lexis", "Ability to think in diverse ways", "Interdisciplinary studies cultivate superior cognitive flexibility and problem-solving."),
                    Band9Vocabulary("Diluting technical rigor", "Formal Collocation", "Weakening educational standards", "Including irrelevant electives risks diluting technical rigor in engineering.")
                ),
                q3Title = "Formal Letter: Transport Disruption & Platform Safety Complaint",
                q3Prompt = "You rely on regional commuter railway services, which have experienced severe cancellations and safety hazards over recent weeks. Write a formal complaint letter to the Minister of Transport.\n\nIn your letter:\n• Explain the severity and frequency of the cancellations\n• Detail how this failure affects workers and local commerce\n• Demand concrete remediation timelines and accountability\n(Write at least 150 words)",
                q3Letter = "Dear Minister Thornton,\n\nI am writing to register an urgent formal complaint regarding the intolerable operational decline of the Northern Commuter Rail Corridor over the past six weeks.\n\nAs a daily commuter representing hundreds of affected professionals, I have observed that scheduled morning express services are now cancelled with alarming regularity—exceeding forty percent of scheduled departures in this quarter alone. When trains do arrive, chronic carriage shortages generate severe overcrowding, posing acute safety hazards on platforms and subjecting elderly passengers to unacceptable distress.\n\nThis continuous dereliction of statutory service standards is inflicting severe economic harm on our regional economy. Small business owners report catastrophic declines in morning retail footfall, while punctual employees face unfair disciplinary reprimands due to transit unreliability. The current compensation framework is entirely insufficient to offset these losses.\n\nI respectfully demand an immediate independent audit of the franchise operator, accompanied by an explicit, legally binding timetable for the restoration of full operational timetables.\n\nYours sincerely,\nEleanor Sterling",
                q3Vocab = listOf(
                    Band9Vocabulary("Dereliction of statutory standards", "Formal Legal Lexis", "Failure in legal duties", "Allowing transit infrastructure to collapse represents a dereliction of statutory standards."),
                    Band9Vocabulary("Alarming regularity", "Collocation", "Happening dangerously often", "Essential services were halted with alarming regularity throughout the winter months."),
                    Band9Vocabulary("Independent audit", "Formal Term", "Neutral inspection", "Civic leaders demanded an immediate independent audit into rail safety."),
                    Band9Vocabulary("Legally binding timetable", "Collocation", "Mandatory schedule", "The operator must sign a legally binding timetable for rolling stock repairs.")
                ),
                q4Title = "Ageing Populations: Economic Crisis vs Societal Wisdom",
                q4Prompt = "In many countries, people are now living longer than ever before. Some people say an ageing population creates problems for governments. Others think there are benefits if society has more elderly people. To what extent do you agree or disagree? (Write at least 250 words)",
                q4Essay = "The remarkable expansion of human life expectancy represents one of the crowning triumphs of modern medicine and public sanitation. However, this demographic shift has ignited heated economic discourse. While pessimists argue that expanding elderly populations impose unsustainable fiscal burdens upon state healthcare and pensions, I believe that the profound social, intellectual, and familial benefits conferred by active senior citizens ensure that longevity remains a net positive for society.\n\nUndeniably, an aging demographic profile poses legitimate fiscal challenges to national treasuries. As the dependency ratio skews toward retirees, a shrinking working-age tax base must finance escalating expenditures for chronic medical care, assisted living infrastructure, and state pension endowments. Without structural reforms—such as raising the retirement age and transitioning toward funded private pensions—governments risk budgetary deficits and reduced allocations for infrastructure and child education.\n\nNonetheless, characterizing older citizens as mere economic liabilities reflects an ungrateful and myopic worldview. Seniors contribute invaluable unpaid labor that stabilizes modern societies. In countless dual-income households, retired grandparents provide indispensable childcare, enabling younger parents to participate fully in the workforce without incurring crippling nursery expenses. Furthermore, senior citizens possess vast reserves of institutional knowledge, moral judgment, and professional expertise that enrich charitable organizations, local governance, and corporate advisory boards. Their presence anchors cultural heritage and instills civic perspective in upcoming generations.\n\nIn conclusion, while the fiscal pressures of an aging population demand prudent legislative and pension reforms, the advantages of a society enriched by senior wisdom are immense. Longevity is a blessing to be celebrated and supported, not a crisis to be feared.",
                q4Vocab = listOf(
                    Band9Vocabulary("Dependency ratio", "Demographic Lexis", "Ratio of non-workers to workers", "A sharply rising dependency ratio strains state social security budgets."),
                    Band9Vocabulary("Myopic worldview", "Critical Lexis", "Short-sighted perspective", "Viewing elderly citizens solely as fiscal burdens reveals a myopic worldview."),
                    Band9Vocabulary("Institutional knowledge", "Corporate Collocation", "Years of collected wisdom", "Retaining senior advisors preserves invaluable institutional knowledge within universities."),
                    Band9Vocabulary("Indispensable childcare", "Collocation", "Essential care for children", "Grandparents provide indispensable childcare that empowers young mothers to work.")
                )
            )

            3 -> WritingSetInfo(
                title = "Cambridge $bookNum Test 3: Public Transport Usage & Global English",
                theme = "Cambridge $bookNum Test 3 • Language Acquisition & Public Transit",
                q1Title = "Commuter Public Transit Usage & Passenger Satisfaction",
                q1Prompt = "The bar chart compares public transit passenger volumes and customer satisfaction ratings across five capital cities.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. (Write at least 150 words)",
                q1Report = "The comparative bar chart details weekly passenger footfall alongside corresponding customer satisfaction percentages across public transportation networks in five major capital cities: City A, City B, City C, City D, and City E.\n\nOverall, there appears to be an inverse correlation between passenger volume and customer satisfaction, with the most heavily congested metropolitan networks recording the lowest approval ratings, while smaller, modern transit grids achieved near-unanimous satisfaction.\n\nCity A reported the highest passenger patronage, transporting roughly 12 million commuters weekly, yet registered an approval rating of only 58%. City B followed with 9.5 million travelers and a modest 64% satisfaction score, reflecting commuter frustration over delays and carriage overcrowding.\n\nIn stark contrast, City D and City E, which handled significantly lighter transit volumes (4 million and 3 million weekly commuters respectively), recorded outstanding customer satisfaction scores of 88% and 92%. City C occupied an intermediate position, balancing 7 million riders with an approval index of 76%.",
                q1Vocab = listOf(
                    Band9Vocabulary("Inverse correlation", "Statistical Lexis", "Opposite relationship", "The data illustrates an inverse correlation between commuter density and transit satisfaction."),
                    Band9Vocabulary("Passenger patronage", "Formal Transport Lexis", "Number of customers using service", "City A recorded the largest passenger patronage across its regional rail network."),
                    Band9Vocabulary("Near-unanimous satisfaction", "Collocation", "Almost 100% happy approval", "The newly opened electric tram line achieved near-unanimous satisfaction."),
                    Band9Vocabulary("Intermediate position", "Data Lexis", "Middle place in comparison", "City C occupied an intermediate position across all metrics.")
                ),
                q2Title = "Language Acquisition: Global English & Social Friction",
                q2Prompt = "Living in a country where you have to speak a foreign language can cause serious social problems, as well as practical problems. To what extent do you agree or disagree with this statement? (Write at least 250 words)",
                q2Essay = "In our globalized era of fluid international migration, millions of expatriates, refugees, and international scholars reside in jurisdictions where they must navigate daily life in a non-native tongue. While some argue that modern translation apps and cosmopolitan diversity reduce communication barriers, I firmly agree that language deficits provoke acute practical complications and severe social alienation.\n\nOn a practical level, linguistic barriers hinder fundamental civic and professional integration. An individual lacking fluency in the host nation's official language struggles with essential administrative tasks: leasing accommodation, interpreting tenancy contracts, understanding emergency medical prescriptions, and liaising with judicial or taxation authorities. In the employment market, even highly qualified engineers or medical doctors are frequently relegated to low-skilled manual labor due to their inability to communicate with nuanced fluency, wasting precious human capital and breeding financial distress.\n\nMore profoundly, language deficits generate severe social estrangement and cultural polarization. Language is not merely a transactional tool; it is the vascular system of humor, cultural idiom, and emotional empathy. When immigrants cannot express subtle thoughts, they naturally retreat into insular linguistic enclaves, rarely interacting with native neighbors. This self-segregation fosters mutual mistrust, enabling xenophobic political narratives to portray immigrants as unwilling to assimilate. Consequently, the host society becomes culturally fractured into parallel communities that share physical space but zero genuine interpersonal solidarity.\n\nIn conclusion, navigating life in an unfamiliar linguistic environment generates profound practical obstacles and systemic social fissures. National governments must fund comprehensive, accessible language immersion programs to transform linguistic vulnerability into inclusive civic participation.",
                q2Vocab = listOf(
                    Band9Vocabulary("Acute practical complications", "Collocation", "Severe real-world problems", "Language deficits induce acute practical complications when seeking emergency healthcare."),
                    Band9Vocabulary("Social estrangement", "Sociological Lexis", "Feeling completely left out", "Linguistic barriers inevitably generate social estrangement between residents."),
                    Band9Vocabulary("Insular linguistic enclaves", "C2 Lexis", "Isolated language pockets", "Failing to learn the host tongue pushes migrants into insular linguistic enclaves."),
                    Band9Vocabulary("Interpersonal solidarity", "Formal Collocation", "Mutual human support", "Genuine intercultural integration requires language fluency and interpersonal solidarity.")
                ),
                q3Title = "Formal Letter: University Postgraduate Fellowship Application",
                q3Prompt = "You wish to apply for a prestigious postgraduate research fellowship at a renowned foreign university. Write a formal application letter to the Dean of Graduate Studies.\n\nIn your letter:\n• Introduce your academic profile and research focus\n• Outline why this institution is ideal for your study\n• Detail how your findings will contribute to global knowledge\n(Write at least 150 words)",
                q3Letter = "Dear Dean Kensington,\n\nI am writing to formally submit my candidacy for the Global Sustainability Postgraduate Fellowship within the Department of Civil and Environmental Engineering for the upcoming academic year.\n\nHaving graduated with first-class honors in Environmental Engineering and authored two peer-reviewed publications on urban hydrology, I have dedicated my recent scholarly endeavors to investigating decentralized storm-water recycling in climate-vulnerable coastal megacities. Your department’s pioneering work under the Urban Resilience Initiative, particularly the cutting-edge hydrodynamic modeling conducted by Dr. Aris Thorne, provides the exact theoretical and technological framework required to advance my research.\n\nShould I be granted this prestigious fellowship, my research will formulate an open-source optimization algorithm tailored specifically for flood mitigation in developing regions. This endeavor directly aligns with your institution's charter of democratizing sustainable infrastructure solutions worldwide.\n\nI have appended my comprehensive curriculum vitae, research synopsis, and academic credentials for your evaluation.\n\nYours sincerely,\nMarcus Holloway",
