                    Band9Vocabulary("Pedagogical utility", "Academic Lexis", "Usefulness for teaching", "Interactive software possesses immense pedagogical utility for mathematics instruction."),
                    Band9Vocabulary("Digital hygiene", "Collocation", "Healthy habits with screens", "Schools must enforce strict digital hygiene during instructional hours.")
                )
